    pageSchema('AboutPage', 'عن النواصرة لتجارة الجملة والمواد الغذائية', '/about/'),
    breadcrumbSchema([{name: 'الرئيسية', route: '/'}, {name: 'عن المحل', route: '/about/'}]),
