              className="grid h-11 w-11 place-items-center rounded-2xl border border-slate-200 bg-[#fffdf8] text-slate-600 md:hidden"
            >
              {mobileSearchOpen ? <X className="h-5 w-5" /> : <Search className="h-5 w-5" />}
