        )}

        <div className="border-t border-slate-100 px-4 py-2 xl:hidden">
          <nav className="mx-auto flex max-w-7xl gap-1 overflow-x-auto pb-1 scrollbar-none" aria-label="التنقل السريع">
            {navigation.map((item) => (
