                aria-current={item.page === activePage ? 'page' : undefined}
                className={`shrink-0 rounded-xl px-3 py-2 text-[10px] font-black ${item.page === activePage ? 'bg-blue-700 text-white' : 'bg-slate-50 text-slate-700'}`}
              >
                {item.label}
              </button>
            ))}
          </nav>
        </div>
      </div>
    </header>
  );
}

