export async function loadBulkImageProducts(canEdit:()=>boolean,onPage:(loaded:number,total:number)=>void):Promise<Product[]>{
 if(!canEdit())throw new Error('ليس لديك صلاحية تعديل المنتجات.');
 const first=await fetchAdminProductPage({page:1,pageSize:100,status:'all',sort:'name'}),rows=[...first.products];
 onPage(rows.length,first.totalCount);
 for(let page=2;page<=first.totalPages;page++){
  if(!canEdit())throw new Error('تغيّرت الجلسة أو الصلاحية؛ توقف تحميل المنتجات.');
  const next=await fetchAdminProductPage({page,pageSize:100,status:'all',sort:'name'});
  if(next.totalCount!==first.totalCount)throw new Error('تغيّرت قائمة المنتجات أثناء تحميلها؛ أعد تحديث القائمة.');
  rows.push(...next.products);onPage(rows.length,first.totalCount);
 }
 const byId=new Map(rows.map(product=>[product.id,product]));
 if(byId.size!==rows.length||rows.filter(product=>!product.flavorMasterProductId).length!==first.totalCount)throw new Error('لم تكتمل قائمة المنتجات. حدّث القائمة قبل اختيار الصور.');
 return rows;
}

export function bulkImageDependencies(journal:ImageJournal,canEdit:()=>boolean,onFresh:(product:Product)=>void):BulkImageDependencies{
 const read=async(id:string)=>{if(!canEdit())throw new Error('ليس لديك صلاحية تعديل المنتجات.');const product=await fetchAdminProductById(id,'any');if(product)onFresh(product);return product;};
 return {journal,canEdit,readProduct:read,upload:uploadProductImageToSupabase,remove:removeBulkUploadedProductImage,
  hasReference:entry=>isUploadedImageReferenced(entry.publicUrl),
  save:async(product,url)=>{
   if(!canEdit())return {success:false,error:'ليس لديك صلاحية تعديل المنتجات.'};
   const latest=await read(product.id);
   if(latest?.imageUrl===url)return {success:true};
   if(!latest||normalizeImageSku(latest.sku)!==normalizeImageSku(product.sku)||(latest.imageUrl??'')!==(product.imageUrl??''))return {success:false,error:'تغيّر رمز الصنف أو صورته؛ حدّث المعاينة قبل الاستبدال.'};
   const result=await saveProductPrimaryImage(product.id,url);
   if(result.success){try{await read(product.id);}catch{/* The committed image remains successful;the page can refresh later. */}}
   return result;
  }};
}

import {validateProductImage} from '../../../utils/productImage';
import type {PreparedImage} from './model';

export const BULK_IMAGE_MAX_SIDE=1200;
export const BULK_IMAGE_TARGET_BYTES=300_000;
const encode=(canvas:HTMLCanvasElement,quality:number)=>new Promise<Blob>((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('تعذر تجهيز الصورة.')),'image/jpeg',quality));

/** Both decoders honor EXIF;canvas output has upright pixels and no EXIF rotation. */
export async function compressProductImage(file:File):Promise<PreparedImage>{
 const validation=validateProductImage(file);if(validation)throw new Error(validation);
 const canvas=document.createElement('canvas'),thumb=document.createElement('canvas');
 let source:ImageBitmap|HTMLImageElement|undefined,url:string|undefined;
 try{
  const bytes=await file.arrayBuffer();
  const fingerprint=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');
  if(typeof createImageBitmap==='function')source=await createImageBitmap(file,{imageOrientation:'from-image'});
  else{url=URL.createObjectURL(file);const image=new Image();image.src=url;await image.decode();source=image;}
  const originalWidth=source instanceof HTMLImageElement?source.naturalWidth:source.width;
  const originalHeight=source instanceof HTMLImageElement?source.naturalHeight:source.height;
  if(!originalWidth||!originalHeight)throw new Error('INVALID_IMAGE');
  const ratio=Math.min(1,BULK_IMAGE_MAX_SIDE/Math.max(originalWidth,originalHeight));
  canvas.width=Math.max(1,Math.round(originalWidth*ratio));canvas.height=Math.max(1,Math.round(originalHeight*ratio));
  const context=canvas.getContext('2d');if(!context)throw new Error('CANVAS_UNAVAILABLE');
  context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(source,0,0,canvas.width,canvas.height);
  let blob=await encode(canvas,0.88);
  for(const quality of [0.78,0.66,0.54,0.42]){if(blob.size<BULK_IMAGE_TARGET_BYTES)break;blob=await encode(canvas,quality);}
  while(blob.size>=BULK_IMAGE_TARGET_BYTES&&Math.max(canvas.width,canvas.height)>240){
   const smaller=document.createElement('canvas');smaller.width=Math.max(1,Math.floor(canvas.width*0.8));smaller.height=Math.max(1,Math.floor(canvas.height*0.8));
   const smallContext=smaller.getContext('2d');if(!smallContext)throw new Error('CANVAS_UNAVAILABLE');smallContext.drawImage(canvas,0,0,smaller.width,smaller.height);
   canvas.width=smaller.width;canvas.height=smaller.height;context.drawImage(smaller,0,0);smaller.width=0;smaller.height=0;blob=await encode(canvas,0.78);
  }
  if(blob.size>=BULK_IMAGE_TARGET_BYTES)throw new Error('IMAGE_TOO_LARGE');
  const thumbRatio=Math.min(1,96/Math.max(canvas.width,canvas.height));thumb.width=Math.max(1,Math.round(canvas.width*thumbRatio));thumb.height=Math.max(1,Math.round(canvas.height*thumbRatio));
  const thumbContext=thumb.getContext('2d');if(!thumbContext)throw new Error('CANVAS_UNAVAILABLE');thumbContext.drawImage(canvas,0,0,thumb.width,thumb.height);
  const thumbnail=await encode(thumb,0.75);
  return {file:new File([blob],file.name.replace(/\.[^.]+$/u,'.jpg'),{type:'image/jpeg',lastModified:file.lastModified}),fingerprint,thumbnail,width:canvas.width,height:canvas.height};
 }catch(error){
  if(error instanceof Error&&error.message==='IMAGE_TOO_LARGE')throw new Error('تعذر ضغط الصورة إلى أقل من 300KB؛ اختر صورة أصغر.',{cause:error});
  throw new Error('ملف الصورة تالف أو تعذر قراءته. اختر صورة JPG أو PNG أو WebP سليمة.',{cause:error});
 }finally{if(source&&'close' in source)source.close();if(url)URL.revokeObjectURL(url);canvas.width=0;canvas.height=0;thumb.width=0;thumb.height=0;}
}

export type ImageJournalStage='prepared'|'uploaded'|'uncertain'|'cleanup_pending'|'confirmed';
export interface ImageJournalEntry{productId:string;fingerprint:string;sku:string;fileName:string;publicUrl:string;storagePath:string;previousImageUrl:string;stage:ImageJournalStage;at:number}
export interface ImageJournal{get(productId:string,fingerprint:string):ImageJournalEntry|undefined;all():ImageJournalEntry[];put(entry:ImageJournalEntry):void;remove(productId:string,fingerprint:string):void}
const uuid=/^[a-f\d]{8}-[a-f\d]{4}-[a-f\d]{4}-[a-f\d]{4}-[a-f\d]{12}$/iu;
const hash=/^[a-f\d]{64}$/u;
const key=(id:string,digest:string)=>id+':'+digest;

/** No image bytes,Auth credentials or tokens. An atomic write precedes Storage. */
export function createImageJournal(storage:Pick<Storage,'getItem'|'setItem'>,origin:string,userId:string):ImageJournal{
 if(!uuid.test(userId))throw new Error('تعذر تحديد حساب رفع الصور.');
 const base=origin.replace(/\/+$/u,''),scope=base+'|'+userId,storageKey='nawasrah-bulk-images-v1:'+scope;
 const validate=(entry:ImageJournalEntry)=>{
  const filename=entry.storagePath?.slice(userId.length+1);
  return uuid.test(entry.productId)&&hash.test(entry.fingerprint)&&entry.storagePath?.startsWith(userId+'/')
   &&typeof filename==='string'&&/^[a-f\d-]{36}\.(jpg|png|webp)$/iu.test(filename)
   &&entry.publicUrl===base+'/storage/v1/object/public/product-images/'+entry.storagePath
   &&['prepared','uploaded','uncertain','cleanup_pending','confirmed'].includes(entry.stage)
   &&typeof entry.previousImageUrl==='string'&&typeof entry.sku==='string'&&typeof entry.fileName==='string'&&Number.isFinite(entry.at);
 };
 let entries:Record<string,ImageJournalEntry>={};
 try{const raw=storage.getItem(storageKey);if(raw){const parsed=JSON.parse(raw) as {version:number;scope:string;entries:ImageJournalEntry[]};
  if(parsed.version!==1||parsed.scope!==scope||!Array.isArray(parsed.entries)||!parsed.entries.every(validate))throw new Error('INVALID_JOURNAL');
  entries=Object.fromEntries(parsed.entries.map(entry=>[key(entry.productId,entry.fingerprint),entry]));
 }}catch{throw new Error('تعذرت قراءة سجل رفع الصور السابق. لا تحذفه؛ تواصل مع المطوّر لفحص الاستئناف.');}
 const persist=(next:Record<string,ImageJournalEntry>)=>{
  const values=Object.values(next).sort((a,b)=>a.at-b.at);
  while(values.length>2000){const index=values.findIndex(e=>e.stage==='confirmed');if(index<0)throw new Error('نظّف عمليات رفع الصور السابقة قبل إضافة دفعة أخرى.');const [removed]=values.splice(index,1);delete next[key(removed.productId,removed.fingerprint)];}
  try{storage.setItem(storageKey,JSON.stringify({version:1,scope,entries:values}));}catch{throw new Error('تعذر حفظ سجل الاستئناف على هذا الجهاز. أفرغ مساحة قبل رفع الصور.');}
  entries=next;
 };
 return {get:(id,digest)=>entries[key(id,digest)],all:()=>Object.values(entries),
  put:entry=>{if(!validate(entry))throw new Error('بيانات استئناف الصورة غير صالحة.');persist({...entries,[key(entry.productId,entry.fingerprint)]:entry});},
  remove:(id,digest)=>{const next={...entries};delete next[key(id,digest)];persist(next);}};
}

import type {Product} from '../../../types';
import type {AuthState} from '../../../stores/useAuthStore';
import {canUseNavigationAction} from '../../more/adminNavigation.config';

export type BulkImageAuth=Pick<AuthState,'isAuthenticated'|'isSessionLocked'|'mfaRequired'|'roleName'|'roles'|'profile'|'user'>;
export function canUploadProductImages(auth:BulkImageAuth):boolean{
 return Boolean(auth.isAuthenticated&&auth.user?.id&&!auth.isSessionLocked&&!auth.mfaRequired&&auth.profile?.is_active!==false
  &&canUseNavigationAction({type:'modal',destination:'add_product'},auth.roleName,auth.roles));
}
export function normalizeImageSku(value:string):string{
 return value.trim().replace(/[\u0660-\u0669\u06f0-\u06f9]/gu,c=>String(c.charCodeAt(0)-(c.charCodeAt(0)<=0x669?0x660:0x6f0))).toUpperCase();
}
export function imageFileSku(name:string):string{return normalizeImageSku(name.replace(/\.[^.]+$/u,''));}
export type MatchKind='matched'|'no_product'|'duplicate'|'ambiguous'|'invalid';
export interface ImageMatch{index:number;file:File;sku:string;kind:MatchKind;product?:Product;error?:string}
export function matchProductImages(files:readonly File[],products:readonly Product[]):ImageMatch[]{
 const catalog=new Map<string,Product[]>(),counts=new Map<string,number>();
 for(const product of products){const key=normalizeImageSku(product.sku);catalog.set(key,[...(catalog.get(key)??[]),product]);}
 for(const file of files){const key=imageFileSku(file.name);counts.set(key,(counts.get(key)??0)+1);}
 return files.map((file,index)=>{
  const sku=imageFileSku(file.name),candidates=catalog.get(sku)??[],base={index,file,sku};
  if(!/\.(jpe?g|png|webp)$/iu.test(file.name)||!sku)return {...base,kind:'invalid',error:'اختر ملف JPG أو PNG أو WebP باسم رمز الصنف.'};
  if((counts.get(sku)??0)>1)return {...base,kind:'duplicate',error:'ملفان أو أكثر لنفس رمز الصنف؛ احذف المكرر قبل الرفع.'};
  if(candidates.length>1)return {...base,kind:'ambiguous',error:'أكثر من منتج له هذا الرمز بعد التطبيع؛ صحح الرموز أولاً.'};
  if(!candidates.length)return {...base,kind:'no_product',error:'لا يوجد منتج أو نكهة بهذا الرمز.'};
  return {...base,kind:'matched',product:candidates[0]};
 });
}
export function activeProductsMissingImages(products:readonly Product[]):Product[]{return products.filter(p=>p.status!=='hidden'&&!p.imageUrl?.trim());}

export interface PreparedImage{file:File;fingerprint:string;thumbnail:Blob;width:number;height:number}
export type RowOutcome='pending'|'working'|'success'|'failed'|'skipped';
export interface BulkImageRow{key:string;match:ImageMatch;prepared?:PreparedImage;previewUrl?:string;preparationError?:string;replace:boolean;outcome:RowOutcome;message?:string}

import type {Product} from '../../../types';
import type {ImageJournal,ImageJournalEntry} from './journal';
import {normalizeImageSku,type BulkImageRow} from './model';

export interface BulkImageDependencies{
 canEdit:()=>boolean;
 journal:ImageJournal;
 readProduct:(id:string)=>Promise<Product|null>;
 upload:(file:File,before:(intent:{storagePath:string;publicUrl:string})=>void,resumePath?:string)=>Promise<{success:boolean;publicUrl?:string;storagePath?:string;error?:string;uncertain?:boolean}>;
 save:(product:Product,url:string)=>Promise<{success:boolean;error?:string;uncertain?:boolean}>;
 remove:(path:string)=>Promise<boolean>;
 hasReference:(entry:ImageJournalEntry)=>Promise<boolean>;
}
export interface ImageRowResult{key:string;outcome:'success'|'skipped'|'failed';message:string}
const message=(error:unknown)=>error instanceof Error?error.message:'تعذر إتمام رفع الصورة. أعد المحاولة.';
const assertPermission=(deps:BulkImageDependencies)=>{if(!deps.canEdit())throw new Error('ليس لديك صلاحية تعديل المنتجات. سجّل الدخول بالحساب المخوّل.');};

/** A fresh server read always precedes deletion:never delete a possibly committed image. */
export async function reconcileImage(entry:ImageJournalEntry,deps:BulkImageDependencies):Promise<'confirmed'|'retained'|'removed'|'pending'>{
 assertPermission(deps);
 try{
  const current=await deps.readProduct(entry.productId);
  if(current?.imageUrl===entry.publicUrl){deps.journal.put({...entry,stage:'confirmed',at:Date.now()});return 'confirmed';}
  if(await deps.hasReference(entry)){deps.journal.put({...entry,stage:'confirmed',at:Date.now()});return 'retained';}
  // A transport failure is not a rollback proof. Replaying the same path/RPC
  // resolves it;never delete while an earlier server write may still commit.
  if(entry.stage==='prepared'||entry.stage==='uncertain')return 'pending';
  // Persist the deletion phase before deleting bytes. If the final journal
  // removal fails, a retry must not reuse a now-deleted Storage object.
  deps.journal.put({...entry,stage:'cleanup_pending',at:Date.now()});
  if(!await deps.remove(entry.storagePath)){deps.journal.put({...entry,stage:'cleanup_pending',at:Date.now()});return 'pending';}
  deps.journal.remove(entry.productId,entry.fingerprint);return 'removed';
 }catch{
  // The durable prepared entry survives a quota/read/network failure too.
  try{deps.journal.put({...entry,stage:entry.stage==='prepared'||entry.stage==='uncertain'?entry.stage:'cleanup_pending',at:Date.now()});}catch{/* Preserve the existing durable intent. */}
  return 'pending';
 }
}

async function uploadRow(row:BulkImageRow,deps:BulkImageDependencies):Promise<ImageRowResult>{
 const result=(outcome:ImageRowResult['outcome'],text:string):ImageRowResult=>({key:row.key,outcome,message:text});
 if(row.match.kind!=='matched'||!row.match.product)return result('skipped',row.match.error??'هذا الملف غير مطابق.');
 if(!row.prepared)return result('failed',row.preparationError??'لم تُجهّز الصورة.');
 const original=row.match.product,prepared=row.prepared;
 let entry=deps.journal.get(original.id,prepared.fingerprint);
 const wasUncertainSave=entry?.stage==='uncertain';
 try{
  assertPermission(deps);
  const current=await deps.readProduct(original.id);
  if(!current||normalizeImageSku(current.sku)!==row.match.sku)throw new Error('تغيّر رمز الصنف أو حُذف المنتج. حدّث المعاينة أولاً.');
  if(entry&&current.imageUrl===entry.publicUrl){deps.journal.put({...entry,stage:'confirmed',at:Date.now()});return result('skipped','رُفعت وحُفظت هذه الصورة سابقاً.');}
  if(entry&&entry.stage==='cleanup_pending'){
   const recovery=await reconcileImage(entry,deps);
   if(recovery==='confirmed')return result('skipped','رُفعت وحُفظت هذه الصورة سابقاً.');
   if(recovery==='retained')return result('skipped','الصورة محفوظة ضمن صور الأصناف؛ تغيّرت الصورة الرئيسية. حدّث المعاينة قبل الاستبدال.');
   if(recovery==='pending')return result('failed','تعذّر التحقق أو تنظيف رفع سابق. أعد المحاولة قبل رفع ملف جديد.');
   entry=undefined;
  }
  if((current.imageUrl??'')!==(original.imageUrl??''))throw new Error('تغيّرت صورة المنتج بعد المعاينة. حدّث المعاينة وراجع خيار الاستبدال.');
  if(current.imageUrl&&!row.replace){
   if(entry&&(entry.stage==='prepared'||entry.stage==='uncertain'))return result('failed','رفع سابق لم يُحسم بعد. راجع الصورة واختر الاستبدال صراحة للاستئناف، أو تواصل مع المطوّر للتنظيف.');
   if(entry&&entry.stage==='uploaded'&&await reconcileImage(entry,deps)==='pending')return result('failed','تنظيف الصورة غير المحفوظة معلّق؛ أعد المحاولة.');
   return result('skipped','لديه صورة حالياً؛ لم تختر استبدالها.');
  }
  if(!current.updatedAt)throw new Error('تعذر تثبيت نسخة المنتج. حدّث المعاينة أولاً.');
  if(entry?.stage==='confirmed'){
   if(await deps.hasReference(entry))entry={...entry,stage:'uploaded',previousImageUrl:current.imageUrl??''};
   else{const clean=await reconcileImage(entry,deps);if(clean==='pending')return result('failed','تنظيف رفع سابق معلّق؛ أعد المحاولة قبل رفع ملف جديد.');if(clean!=='removed')return result('skipped','تم التحقق من وجود الصورة؛ حدّث المعاينة.');entry=undefined;}
  }
  if(!entry||entry.stage==='prepared'){
   const resumePath=entry?.storagePath;
   const intentHolder:{entry?:ImageJournalEntry}={};
   const uploaded=await deps.upload(prepared.file,intent=>{
    assertPermission(deps);
    const intentEntry:ImageJournalEntry={...intent,productId:current.id,fingerprint:prepared.fingerprint,sku:current.sku,fileName:row.match.file.name,previousImageUrl:current.imageUrl??'',stage:'prepared',at:Date.now()};
    deps.journal.put(intentEntry);intentHolder.entry=intentEntry;entry=intentEntry;
   },resumePath);
   if(!uploaded.success||!uploaded.publicUrl||!uploaded.storagePath){
    throw new Error(uploaded.error??'تعذر رفع الصورة.');
   }
   const intent=intentHolder.entry;
   if(!intent||intent.publicUrl!==uploaded.publicUrl||intent.storagePath!==uploaded.storagePath)throw new Error('تعذر ربط نتيجة الرفع بسجل الاستئناف.');
   entry={...intent,stage:'uploaded',at:Date.now()};deps.journal.put(entry);
  }
  assertPermission(deps);
  entry={...entry,stage:'uncertain',at:Date.now()};deps.journal.put(entry);
  const saved=await deps.save(current,entry.publicUrl);
  if(!saved.success){
   if(!saved.uncertain&&!wasUncertainSave){entry={...entry,stage:'uploaded'};deps.journal.put(entry);}
   throw new Error(saved.error??'تعذر حفظ صورة المنتج.');
  }
  deps.journal.put({...entry,stage:'confirmed',at:Date.now()});
  return result('success','تم رفع الصورة وحفظها.');
 }catch(error){
  const reason=message(error);
  if(entry&&entry.stage!=='confirmed'){
   const reconciled=await reconcileImage(entry,deps).catch(()=>'pending' as const);
   if(reconciled==='confirmed')return result('success','تم التحقق من حفظ الصورة بعد انقطاع الرد.');
   if(reconciled==='retained')return result('skipped','الصورة محفوظة ضمن صور الأصناف؛ لم تُحذف. راجع الصورة الرئيسية قبل الاستبدال.');
   if(reconciled==='pending')return result('failed',reason+' التحقق والتنظيف معلّقان في سجل الاستئناف؛ أعد المحاولة.');
  }
  return result('failed',reason);
 }
}

/** Exactly two workers; a route change stops new work after in-flight cleanup. */
export async function runBulkImageUpload(rows:readonly BulkImageRow[],deps:BulkImageDependencies,onRow:(result:ImageRowResult)=>void,signal?:AbortSignal):Promise<ImageRowResult[]>{
 assertPermission(deps);
 if(rows.some(row=>row.match.kind==='duplicate'||row.match.kind==='ambiguous'))throw new Error('صحح الرموز المكررة أو الملتبسة في المعاينة قبل أي رفع.');
 let next=0;const results:ImageRowResult[]=[];
 const worker=async()=>{while(next<rows.length&&!signal?.aborted){const row=rows[next++];const result=await uploadRow(row,deps);results.push(result);onRow(result);}};
 await Promise.all([worker(),worker()]);return results;
}

export async function withBulkImageLock<T>(scope:string,work:()=>Promise<T>):Promise<T>{
 if(!navigator.locks)throw new Error('المتصفح لا يدعم الاستئناف الآمن هنا. افتح آخر إصدار من Chrome أو Safari.');
 return navigator.locks.request('nawasrah-bulk-images:'+scope,{ifAvailable:true},async lock=>{
  if(!lock)throw new Error('هناك رفع صور جارٍ في نافذة أخرى. انتظر اكتماله ثم أعد المحاولة.');return work();
 });
}

